terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_route53_zone" "primary" {
  name = "example53.com"
}

# Health check for the primary resource
resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = "example.com"
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
}

# Primary A record with a health check (active endpoint)
resource "aws_route53_record" "primary_record" {
  zone_id           = aws_route53_zone.primary.zone_id
  name              = "example.com"
  type              = "A"
  ttl               = "60"
  records           = ["192.0.2.10"]
  set_identifier    = "primary"
  health_check_id   = aws_route53_health_check.primary_health_check.id

  failover_routing_policy {
    type = "PRIMARY"
  }
}

# Secondary A record without a health check (passive endpoint)
resource "aws_route53_record" "secondary_record" {
  zone_id           = aws_route53_zone.primary.zone_id
  name              = "example.com"
  type              = "A"
  ttl               = "60"
  records           = ["192.0.2.20"]
  set_identifier    = "secondary"

  failover_routing_policy {
    type = "SECONDARY"
  }
}

responsePreview:
The following Terraform configuration creates a Route 53 public hosted zone named `primary`, defines a Route 53 health check resource named `primary_health_check` using an FQDN, and configures active-passive DNS failover records. The primary record is monitored by the health check, while the secondary record is used when the primary endpoint is unhealthy.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region used for provider configuration."
  type        = string
  default     = "us-east-1"
}

variable "zone_name" {
  description = "The DNS name for the Route 53 hosted zone."
  type        = string
  default     = "example.com"
}

variable "application_record_name" {
  description = "The DNS record name used for active-passive failover."
  type        = string
  default     = "app.example.com"
}

variable "primary_endpoint_fqdn" {
  description = "The fully qualified domain name of the primary endpoint."
  type        = string
  default     = "primary-origin.example.com"
}

